<?php declare(strict_types=1); ?>
<section class="section"><div class="container-wide"><div class="section-heading"><p class="eyebrow">Restricted administration</p><h1>Programme applications</h1><p>Review submitted professional-programme applications and manage authorized lifecycle actions.</p></div>
<?php if($message):?><div class="notice" role="status"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="form-error" role="alert"><?= $e($error) ?></div><?php endif;?>
<form method="get" action="/admin/programme-applications" class="form-grid"><label>Search<input name="search" maxlength="100" value="<?= $e($filters['search']??'') ?>"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(['submitted','review','approved','rejected','enrolled','completed','withdrawn'] as $status):?><option value="<?= $status ?>" <?= ($filters['status']??'')===$status?'selected':'' ?>><?= $e(ucwords($status)) ?></option><?php endforeach;?></select></label><button class="btn btn-navy" type="submit">Filter</button></form>
